_DETAIL_ROWS.pop("ha", None)

_EXPECTED_DETAIL_CODES = {
    code for code, _label in LANGUAGE_OPTIONS if code != "en"
}
if set(_DETAIL_ROWS) != _EXPECTED_DETAIL_CODES:
    raise ValueError(
        "Help-post detail catalogs must cover all non-English locales"
    )
if len(HELP_POST_DETAIL_KEYS) != 11 or len(set(HELP_POST_DETAIL_KEYS)) != 11:
    raise ValueError("Help-post detail keys must contain 11 unique sources")

HELP_POST_DETAIL_CATALOGS: dict[str, dict[str, str]] = {
    language: dict(zip(HELP_POST_DETAIL_KEYS, row.split("|"), strict=True))
    for language, row in _DETAIL_ROWS.items()
}
